// The identity migration as better-auth would write it today, compiled against an empty throwaway database.
import { testDb } from "@bodhchakra/db";
import pg from "pg";
import { compileIdentitySchema } from "../src/identity.ts";

export const HEADER = `-- GENERATED by scripts/identity-sql.ts from better-auth's schema for the options in src/identity.ts.
-- Do not edit; test/identity-schema.test.ts fails if this drifts. The grants are in 0002_grant.sql.
`;

export async function identitySql(): Promise<string> {
  const db = await testDb({ owner: "platform_owner", runtimeRole: "platform_app", folders: [] });
  const pool = new pg.Pool({ connectionString: db.url("platform_owner"), max: 1 });
  try {
    const sql = await compileIdentitySchema(pool);
    return `${HEADER}${sql.trim()}\n`;
  } finally {
    await pool.end();
    await db.drop();
  }
}
